export type Range = { low: number; high: number };

export type StructuralComponents = {
  access: Range;
  conversions: Range;
  pathway: Range;
  missionFit: Range;
  party: Range;
  runway: Range;
};

export type RegimeId = "equilibrium" | "control" | "readiness" | "technical";

export type BoardCandidate = {
  officerId: string;
  tier: "Tier 1" | "Tier 2" | "Tier 3" | "Feeder watch";
  rankBand: string;
  scoreRange: Range;
  components: StructuralComponents;
  path: string;
  nextGate: string;
  disconfirmer: string;
  regimeFit: Record<RegimeId, "High" | "Medium" | "Low">;
  stableRegimes: number;
  conditions?: { label: string; scoreRange: Range }[];
};

const total = (components: StructuralComponents): Range => ({
  low: Object.values(components).reduce((sum, value) => sum + value.low, 0),
  high: Object.values(components).reduce((sum, value) => sum + value.high, 0),
});

type CandidateInput = Omit<BoardCandidate, "scoreRange" | "stableRegimes"> & { stableRegimes?: number };

const makeCandidate = (candidate: CandidateInput): BoardCandidate => ({
  ...candidate,
  stableRegimes: Object.values(candidate.regimeFit).filter((fit) => fit !== "Low").length,
  scoreRange: total(candidate.components),
});

